input.command:
cd /repo/evals/terraform-secure-iac/results/raw/2026-10-28/tsi-03-network-modules/with-skill/run-1/workspace
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  backend "s3" {
    bucket       = "network-terraform-state"
    key          = "network/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat >> variables.tf <<'EOF'

variable "vpc_cidr" {
  type        = string
  description = "IPv4 CIDR block of the VPC."
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  type        = list(string)
  description = "Availability zones that each get one private subnet. Order must match private_subnet_cidrs."
  default     = ["eu-north-1a", "eu-north-1b"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "IPv4 CIDR blocks of the private subnets, one per entry in availability_zones."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}
EOF
cat > vpc.tf <<'EOF'
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "6.7.3"

  name = "${module.labels.tags["Service"]}-${var.environment}"
  cidr = var.vpc_cidr

  azs             = var.availability_zones
  private_subnets = var.private_subnet_cidrs

  enable_nat_gateway = false

  tags = module.labels.tags
}
EOF
grep -rn "output\|tags" /dev/null; terraform fmt -recursive -check -diff; terraform init -backend=false 2>&1 | tail -15

